import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"媒体播放（libmpv）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/media.md","filePath":"zh/guide/media.md","lastUpdated":1790847150000}'),n={name:"zh/guide/media.md"};function p(l,a,d,o,r,h){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="媒体播放-libmpv" tabindex="-1">媒体播放（libmpv） <a class="header-anchor" href="#媒体播放-libmpv" aria-label="Permalink to &quot;媒体播放（libmpv）&quot;">​</a></h1><p>桌面端，NeoFlux 可通过 <a href="https://mpv.io" target="_blank" rel="noreferrer">libmpv</a> 的<strong>渲染 API</strong> 渲染视频。 mpv 不另开窗口，而是由 NeoFlux 已有的 OpenGL 上下文驱动渲染：每帧解码后的视频 变成一张普通 GL 纹理，像其它内容一样由 widget 绘制。</p><div class="warning custom-block"><p class="custom-block-title">可选功能</p><p>桌面视频支持受编译宏 <code>NEOFLUX_HAS_MPV</code> 控制，构建时需要 libmpv 开发文件。 未开启时媒体 API 不参与编译，框架其余部分照常工作。</p></div><h2 id="如何融入两层模型" tabindex="-1">如何融入两层模型 <a class="header-anchor" href="#如何融入两层模型" aria-label="Permalink to &quot;如何融入两层模型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+------------------ 应用线程 ------------------+</span></span>
<span class="line"><span>|  MediaPlayer widget                           |</span></span>
<span class="line"><span>|    mpv_command(mpv, &quot;loadfile&quot;, path)         |</span></span>
<span class="line"><span>|    播放 / 暂停 / 拖动                          |</span></span>
<span class="line"><span>+----------------------------------------------+</span></span>
<span class="line"><span>                     |</span></span>
<span class="line"><span>                     |  mpv 渲染上下文“需要更新”回调</span></span>
<span class="line"><span>                     v</span></span>
<span class="line"><span>+------------------ 渲染线程（持有 GL 上下文）---+</span></span>
<span class="line"><span>|  mpv_render_context_render() -&gt; 写入 GL FBO     |</span></span>
<span class="line"><span>|  得到的帧成为一张 GL 纹理                       |</span></span>
<span class="line"><span>|  Texture widget 像普通命令一样绘制它            |</span></span>
<span class="line"><span>+------------------------------------------------+</span></span></code></pre></div><ol><li><strong>mpv 渲染上下文</strong>绑定到渲染线程已持有的同一个 OpenGL 上下文（桌面端即 GLFW/WGL 上下文）。</li><li>mpv 异步解码文件，在有新帧时回调“需要更新”，该回调请求渲染线程重绘。</li><li>渲染线程调用 <code>mpv_render_context_render()</code> 把解码帧画到离屏 GL framebuffer/纹理， NeoFlux 随后为该纹理发出普通的“画纹理”渲染命令，视频因此能像其它 widget 一样 合成（背景、文字叠加、裁剪都生效）。</li></ol><p>由于所有 mpv 渲染都在持有 GL 上下文的渲染线程上发生，无需迁移上下文。</p><h2 id="播放真实文件" tabindex="-1">播放真实文件 <a class="header-anchor" href="#播放真实文件" aria-label="Permalink to &quot;播放真实文件&quot;">​</a></h2><p>播放接受真实媒体文件路径（或 mpv 支持的任意 URL）：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 仅在 NEOFLUX_HAS_MPV 开启时编译。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MediaPlayer player;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">player.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetSource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tests/data/sample.mp4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">player.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Play</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>控制走底层 mpv 命令：</p><table tabindex="0"><thead><tr><th>操作</th><th>mpv 命令</th></tr></thead><tbody><tr><td>加载文件</td><td><code>loadfile &lt;path&gt; replace</code></td></tr><tr><td>播放 / 暂停</td><td><code>set pause no</code> / <code>set pause yes</code></td></tr><tr><td>拖动进度</td><td><code>seek &lt;秒&gt; absolute</code></td></tr><tr><td>停止</td><td><code>stop</code></td></tr></tbody></table><h2 id="示例测试片段" tabindex="-1">示例测试片段 <a class="header-anchor" href="#示例测试片段" aria-label="Permalink to &quot;示例测试片段&quot;">​</a></h2><p>仓库附带 <code>tests/data/sample.mp4</code>，是一段短小、自包含的视频，供媒体测试与演示使用。 让 <code>MediaPlayer</code> 指向它即可端到端验证播放，无需下载外部素材：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">media_demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.exe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">用 --logtostderr</p><p>mpv 会打印大量诊断信息。加 <code>--logtostderr</code> 才能在终端看到（示例默认是 GUI 子系统、无控制台）。</p></div><h2 id="依赖要求" tabindex="-1">依赖要求 <a class="header-anchor" href="#依赖要求" aria-label="Permalink to &quot;依赖要求&quot;">​</a></h2><ul><li>构建期可用的 libmpv（<code>mpv/client.h</code>、<code>mpv/render_gl.h</code>）。</li><li>桌面 GL 路径（<code>--render_backend=gl</code>），因为渲染上下文包裹 OpenGL 上下文。</li><li>你的 mpv 构建所带 ffmpeg/libav 能解码所用封装/编码格式。</li></ul><h2 id="本工作树中未能核对的内容" tabindex="-1">本工作树中未能核对的内容 <a class="header-anchor" href="#本工作树中未能核对的内容" aria-label="Permalink to &quot;本工作树中未能核对的内容&quot;">​</a></h2><p><code>docs/bilingual</code> 工作树当前并不包含 <code>MediaPlayer</code> 源码或 <code>NEOFLUX_HAS_MPV</code> 的 CMake 接线。本页记录的是项目规划中的桌面媒体架构；发布产品构建前，请对照主检出里的 媒体源码确认确切的类名与 CMake 选项。</p>`,20)])])}const g=s(n,[["render",p]]);export{k as __pageData,g as default};
